<?php

declare(strict_types=1);

namespace App\Domains\Seerah\Dataset\Parsing;

use App\Domains\Seerah\Canonical\CanonicalSection;
use App\Domains\Seerah\Enums\SectionLevel;
use App\Domains\Seerah\Validation\IssueBag;

/**
 * Parses book/structure.json (generated by seerah:canonicalize). Returns the pins it records and its sections.
 */
final class StructureParser
{
    private const array KEYS = ['format', 'source_sha256', 'canonical_sha256', 'counts', 'sections'];

    private const array SECTION_KEYS = ['id', 'level', 'title', 'page', 'paragraph_from', 'paragraph_to'];

    /**
     * @param  array<array-key, mixed>  $decoded
     * @return array{source: string, canonical: string, sections: list<CanonicalSection>}
     */
    public function parse(array $decoded, string $where, IssueBag $issues): array
    {
        FragmentParser::checkFormat($decoded, $where, $issues);
        $reader = new RecordReader($decoded, $where, 'V1', $issues);
        $reader->expectKeys(self::KEYS);

        return [
            'source' => $reader->string('source_sha256'),
            'canonical' => $reader->string('canonical_sha256'),
            'sections' => $reader->objectList('sections', fn (array $item, string $at): CanonicalSection => $this->section($item, $at, $issues)),
        ];
    }

    /**
     * @param  array<array-key, mixed>  $item
     */
    private function section(array $item, string $where, IssueBag $issues): CanonicalSection
    {
        $reader = new RecordReader($item, $where, 'V1', $issues);
        $reader->expectKeys(self::SECTION_KEYS);
        $level = $reader->enumOf('level', SectionLevel::class, SectionLevel::Heading);

        return new CanonicalSection(
            id: $reader->string('id'),
            level: $level instanceof SectionLevel ? $level : SectionLevel::Heading,
            title: $reader->string('title'),
            page: $reader->int('page'),
            paragraphFrom: $reader->nullableString('paragraph_from'),
            paragraphTo: $reader->nullableString('paragraph_to'),
        );
    }
}
